<template>
  <section class="flex flex-col gap-10">
    <PageTitle title="Create Voter's Info" />
    <Card class="max-w-md w-full mx-auto">
      <CardContent>
        <LabeledEntityProject v-if="projectId" :project-id="projectId" />
        <SignatoriesForm
          v-if="!isConversationSubmitted"
          class="mt-4"
          :is-loading="isCreateVerificationVotersLoading"
          @submit="submitSignatories"
          @cancel="cancel"
        />
        <div v-else class="flex flex-col gap-4 w-full mt-4">
          <Alert variant="success">
            <CheckIcon />
            <AlertTitle>Signatories Submitted</AlertTitle>
            <AlertDescription
              >Thank you for your contribution.<br />You can submit new signatories now.
            </AlertDescription>
          </Alert>
          <Button
            class="h-10 w-full flex items-center gap-2"
            variant="outline"
            @click="
              navigateTo({
                name: 'verification-signatory',
                query: { project_id: projectId || undefined },
              })
            "
          >
            <RepeatIcon class="w-5 h-5 stroke-muted-foreground" />
            Submit New Signatories
          </Button>
        </div>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import SignatoriesForm from '~/components/verification/SignatoriesForm.vue';
import { useCreateVerificationVoters } from '~/mutations/verification/voter';
import { RepeatIcon, CheckIcon } from 'lucide-vue-next';
import type { SignatoryVoiceForm } from '~/client';

definePageMeta({
  roles: ['canvasser', 'subcontractor_canvasser'],
});

useHead({
  title: 'Signatory Verification',
});

const route = useRoute();
if (!route.query.project_id) await navigateTo({ name: 'verification-signatory' }, { replace: true });

const { createVerificationVoters, isCreateVerificationVotersLoading } = useCreateVerificationVoters();

const projectId = ref<string | null>(null);
const isConversationSubmitted = ref<boolean>(false);

onMounted(async () => {
  if (route.query.project_id) {
    projectId.value = route.query.project_id as string;
  }
});

async function submitSignatories(infos: SignatoryVoiceForm[]) {
  if (projectId.value) {
    await createVerificationVoters({
      project_id: projectId.value,
      infos: infos,
    }).then(() => (isConversationSubmitted.value = true));
  }
}

async function cancel() {
  await navigateTo({ name: 'verification-signatory' });
}

onUnmounted(() => {
  isConversationSubmitted.value = false;
});
</script>

<style scoped lang="scss"></style>
