<template>
  <div class="flex flex-col gap-4">
    <Card v-for="(signatoryInfo, sIndex) in signatoryInfos" :key="signatoryInfo.id">
      <CardHeader>
        <CardTitle>Signatory Information #{{ sIndex + 1 }}</CardTitle>
      </CardHeader>
      <CardContent class="grid grid-cols-1 sm:grid-cols-2 gap-2">
        <VerificationVoiceFormInput
          v-for="(value, key, index) in signatoryInfoLabels"
          :key="index"
          v-model="signatoryInfo[key]"
          :label="signatoryInfoLabels[key]"
          :maska="key === 'zip_code' ? '#####' : undefined"
          :date-picker="key === 'signed_date'"
          :class="{ 'sm:col-span-1': index < 6, 'sm:col-span-2': index >= 6 }"
        />
      </CardContent>
      <CardFooter class="justify-between">
        <span />
        <Button variant="outline-destructive" class="float-right" @click="removeSignatory(signatoryInfo.id)"
          >Remove
        </Button>
      </CardFooter>
    </Card>
    <Button :prepend-icon="PlusIcon" variant="outline" class="mx-auto" @click="addNewSignatory"
      >Add New Signatory
    </Button>
    <Separator />
    <div class="flex gap-2 flex-wrap">
      <Button variant="outline-destructive" class="h-10 flex-auto min-w-40" @click="emit('cancel')">Cancel</Button>
      <Button
        variant="default"
        :disabled="!isSubmitEnabled || isLoading"
        :loading="isLoading"
        class="h-10 flex-auto min-w-40"
        @click="emit('submit', signatoryInfos)"
      >
        Submit
      </Button>
    </div>
  </div>
</template>

<script setup lang="ts">
import { PlusIcon } from 'lucide-vue-next';
import type { SignatoryUiForm } from '~/client';
import SignatoryInfoSchema from '~/constants/validationSchemas/signatoryInfo';

interface Props {
  isLoading: boolean;
}

defineProps<Props>();

interface Emits {
  (e: 'submit', infos: SignatoryUiForm[]): void;
  (e: 'cancel'): void;
}

const emit = defineEmits<Emits>();

interface SignatoryUiFormWithId extends SignatoryUiForm {
  id: string;
}

const signatoryInfos = ref<SignatoryUiFormWithId[]>([]);

function addNewSignatory() {
  signatoryInfos.value.push({
    id: crypto.randomUUID(),
    first_name: '',
    middle_name: '',
    last_name: '',
    state: '',
    city: '',
    county: '',
    address_1: '',
    address_2: null,
    zip_code: '',
    signed_date: formatDateToFormat(new Date(), 'yyyy-MM-dd'),
  });
}

function removeSignatory(id: string) {
  signatoryInfos.value = signatoryInfos.value.filter((info) => info.id !== id);
}

const signatoryInfoLabels: Record<keyof SignatoryUiForm, string> = {
  first_name: 'First Name',
  last_name: 'Last Name',
  middle_name: 'Middle Name',
  state: 'State',
  city: 'City',
  county: 'County',
  address_1: 'Address',
  address_2: 'Address (line 2)',
  zip_code: 'ZIP Code',
  signed_date: 'Signed Date',
};

const isSubmitEnabled = computed<boolean>(() => {
  return (
    signatoryInfos.value.every((signatoryInfo) => {
      const parsedResult = SignatoryInfoSchema.safeParse(signatoryInfo);
      return parsedResult.success;
    }) && signatoryInfos.value.length > 0
  );
});
</script>

<style scoped lang="scss"></style>
