import { createVerificationVoters } from '~/client';
import type { VerificationVoterCreateRequest, VerificationVoterCreateResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useCreateVerificationVoters = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: VerificationVoterCreateRequest): Promise<VerificationVoterCreateResponse> =>
      createVerificationVoters({
        composable: '$fetch',
        body: ref(data),
      }),
    onSuccess: async () => {
      showToastSuccess(`Signatories created successfully`);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    createVerificationVoters: mutateAsync,
    isCreateVerificationVotersLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
